use super::*;

/// ⏱️ The same original full normal cursor funds every effect and retains exact source/output custody through six interruptions.
#[test]
fn original_mesh_tessellation_normal_cursor_preserves_all_actual_receipts(){
    use crate::brep::queries::tessellation::tests::observe_tessellation_system as observe;
    use protocol::value::{retained_clone::{RetainedCloneGrant,RetainedCloneProgress},retirement::controlled::ControlledRetirement};
    let law:serde_json::Value=serde_json::from_str(include_str!("../../../🧫️fixtures/🧩️tessellation/🎟️owners.json")).unwrap();
    for close_copy in law["copyGrants"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize){for cut in std::iter::once(None).chain(law["normalTessellation"]["cancellationTurns"].as_array().unwrap().iter().map(|value|Some(value.as_u64().unwrap()as usize))){
        let(mut job,source)=observe(||MeshTessellationJob::new(super::tessellation_metadata_tests::authored_source(&law)));let original=job.mesh.vertices.as_ptr();let originals:Vec<_>=job.mesh.attributes.iter().map(|(key,attribute)|(key.clone(),key.as_ptr()as usize,attribute.values.as_ptr()as usize)).collect();let(mut born,mut freed,mut turns,mut completed)=(source.0,source.1,0,None);
        loop{
            if cut==Some(turns){let(_,heap)=observe(||job.cancel());assert_eq!(heap,(0,0));let((step,receipt),heap)=observe(||job.step(RetainedCloneGrant::default()).unwrap());assert_eq!(heap,(0,0));assert_eq!(receipt,RetainedCloneProgress::default());assert!(matches!(step,MeshTessellationStep::Cancelled(_)));break;}
            let copy=job.next_normal_copy_byte_demand().unwrap();let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:law["normalTessellation"]["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:job.next_normal_capacity_byte_demand(128).unwrap(),maximum_release_bytes:job.next_normal_release_byte_demand().unwrap(),maximum_depth:job.next_normal_depth_demand().unwrap()};
            for denied in[Some(RetainedCloneGrant {maximum_items:0,..grant}),(grant.maximum_capacity_bytes>0).then_some(RetainedCloneGrant {maximum_capacity_bytes:grant.maximum_capacity_bytes.saturating_sub(1),..grant}),(grant.maximum_release_bytes>0).then_some(RetainedCloneGrant {maximum_release_bytes:grant.maximum_release_bytes.saturating_sub(1),..grant}),(grant.maximum_depth>0).then_some(RetainedCloneGrant {maximum_depth:grant.maximum_depth.saturating_sub(1),..grant}),(job.normal_output_is_atomic()&&copy>0).then_some(RetainedCloneGrant {maximum_copy_bytes:copy.saturating_sub(1),..grant})].into_iter().flatten(){let before=(job.face,job.phase,job.cursor,job.done,job.normal_output_bytes);let((step,receipt),heap)=observe(||job.step(denied).unwrap());assert!(matches!(step,MeshTessellationStep::Working(_)));assert_eq!(receipt,RetainedCloneProgress::default());assert_eq!(job.normal_step_progress(),receipt);assert_eq!(heap,(0,0));assert_eq!((job.face,job.phase,job.cursor,job.done,job.normal_output_bytes),before);assert_eq!(job.mesh.vertices.as_ptr(),original);}
            let((step,receipt),heap)=observe(||job.step(grant).unwrap());assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));assert_eq!(receipt,job.normal_step_progress());assert!(receipt.fits(grant));assert!(receipt.copied_items<=1);born+=heap.0;freed+=heap.1;turns+=1;assert!(turns<100000);assert_eq!(job.mesh.vertices.as_ptr(),original);
            for(key,key_address,values_address)in&originals{let row=job.mesh.attributes.get_key_value(key).or_else(||job.attribute_pending.as_ref().filter(|(pending,_)|pending==key).map(|(key,attribute)|(key,attribute))).or_else(||job.output.as_ref().and_then(|output|output.attributes.get_key_value(key))).or_else(||if let MeshTessellationStep::Done(output)=&step{output.attributes.get_key_value(key)}else{None}).unwrap();assert_eq!(row.0.as_ptr()as usize,*key_address);assert_eq!(row.1.values.as_ptr()as usize,*values_address);}
            match step{MeshTessellationStep::Working(_)=>{},MeshTessellationStep::Done(output)=>{completed=Some(output);break;},_=>panic!("unrequested original tessellation cancellation")}
        }
        if let Some(output)=&completed{macro_rules! same{($field:ident,$ty:ty)=>{assert_eq!(output.$field,serde_json::from_value::<Vec<$ty>>(law["normalTessellation"][stringify!($field)].clone()).unwrap());};}same!(positions,f32);same!(normals,f32);same!(colors,f32);same!(uvs,f32);same!(indices,u32);assert_eq!(output.vertex_ids,serde_json::from_value::<Vec<u32>>(law["normalTessellation"]["vertexIds"].clone()).unwrap());assert_eq!(output.face_ids,serde_json::from_value::<Vec<u32>>(law["normalTessellation"]["faceIds"].clone()).unwrap());assert_eq!(output.edge_positions,serde_json::from_value::<Vec<f32>>(law["normalTessellation"]["edgePositions"].clone()).unwrap());assert_eq!(output.edge_uvs,serde_json::from_value::<Vec<f32>>(law["normalTessellation"]["edgeUvs"].clone()).unwrap());assert_eq!(output.edge_ids,serde_json::from_value::<Vec<u32>>(law["normalTessellation"]["edgeIds"].clone()).unwrap());assert_eq!(output.edge_is_seam,serde_json::from_value::<Vec<u8>>(law["normalTessellation"]["edgeIsSeam"].clone()).unwrap());assert_eq!(job.normal_output_bytes,law["normalTessellation"]["publishedBufferBytes"].as_u64().unwrap()as usize);}
        let(mut job_owner,handoff)=observe(||ControlledRetirement::new(job).unwrap_or_else(|_|panic!("original normal Job closure unsupported")));assert_eq!(handoff,(0,0));let(mut output_owner,handoff)=observe(||ControlledRetirement::new(completed).unwrap_or_else(|_|panic!("original normal output closure unsupported")));assert_eq!(handoff,(0,0));
        for owner in[&mut job_owner as&mut dyn protocol::value::retirement::controlled::ErasedControlledRetirement,&mut output_owner]{while !owner.terminal_is_empty(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:close_copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(close_copy).unwrap(),maximum_release_bytes:owner.next_release_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand().unwrap()};let(step,heap)=observe(||owner.step(grant).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(step.progress().fits(grant));born+=heap.0;freed+=heap.1;turns+=1;assert!(turns<100000);}}
        assert_eq!(born,freed);let(_,heap)=observe(||{drop(job_owner);drop(output_owner);});assert_eq!(heap,(0,0));eprintln!("[DEBUG] Original Mesh normal copyPolicy128 closeCopy={close_copy} cut={cut:?} oneEvent=true sameSource=true sameOriginalAttributeRows=true physical={freed} terminalDrop=0");
    }}
}
